import java.math.BigDecimal;
import java.util.List;

public class Menos50 implements Cupom {
    private static final BigDecimal MINIMO = new BigDecimal("300.00");
    private static final BigDecimal DESCONTO = new BigDecimal("50.00");

    @Override
    public BigDecimal calcularDesconto(List<ItemRequest> itens, BigDecimal frete) {
        return DESCONTO;
    }

    @Override
    public boolean verificarAplicavel(List<ItemRequest> itens) {
        BigDecimal subtotal = itens.stream()
            .map(item -> item.precoUnitario().multiply(new BigDecimal(item.quantidade())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);

        return subtotal.compareTo(MINIMO) >= 0;
    }
}

